import React, { useState } from "react";
import axios from "axios";

function App() {
  const [query, setQuery] = useState("");
  const [answer, setAnswer] = useState("");
  const [audio, setAudio] = useState(null);
  const [loading, setLoading] = useState(false);

  // TEXT QUERY
  const handleAsk = async () => {
    if (!query.trim()) return;

    setLoading(true);
    setAnswer("");
    setAudio(null);

    try {
      const res = await axios.get(
        `http://127.0.0.1:8000/api/v1/rag/ask?query=${query}`
      );

      setAnswer(res.data.answer);
    } catch (err) {
      console.error(err);
      setAnswer("❌ Error fetching response");
    }

    setLoading(false);
  };

  // VOICE QUERY
  const handleVoice = async () => {
    setLoading(true);
    setAnswer("Listening... 🎤");
    setAudio(null);

    try {
      const res = await axios.post(
        "http://127.0.0.1:8000/api/v1/voice/ask"
      );

      setAnswer(res.data.answer);

      // ✅ FIXED: use /static
      setAudio(`http://127.0.0.1:8000/static/${res.data.audio_file}`);
    } catch (err) {
      console.error(err);
      setAnswer("❌ Voice processing error");
    }

    setLoading(false);
  };

  return (
  <div style={{
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    height: "100vh",
    background: "#f5f7fb",
    fontFamily: "Arial"
  }}>
    <div style={{
      background: "white",
      padding: "30px",
      borderRadius: "12px",
      boxShadow: "0 4px 20px rgba(0,0,0,0.1)",
      width: "400px",
      textAlign: "center"
    }}>
      <h2>🇮🇳 Sarkari Saathi AI</h2>

      <input
        type="text"
        placeholder="Ask about schemes..."
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        style={{
          padding: "12px",
          width: "100%",
          borderRadius: "8px",
          border: "1px solid #ddd",
          marginBottom: "15px"
        }}
      />

      <div>
        <button
          onClick={handleAsk}
          style={{
            padding: "10px 20px",
            borderRadius: "8px",
            border: "none",
            background: "#4CAF50",
            color: "white",
            cursor: "pointer"
          }}
        >
          Ask
        </button>

        <button
          onClick={handleVoice}
          style={{
            padding: "10px 20px",
            borderRadius: "8px",
            border: "none",
            background: "#2196F3",
            color: "white",
            marginLeft: "10px",
            cursor: "pointer"
          }}
        >
          🎤 Voice
        </button>
      </div>

      <div style={{ marginTop: "20px" }}>
        <h4>Answer</h4>
        <p style={{ color: "#333" }}>{answer}</p>
      </div>

      {audio && (
        <audio controls autoPlay style={{ marginTop: "10px" }}>
          <source src={audio} type="audio/mpeg" />
        </audio>
      )}
    </div>
  </div>
  );
}

export default App;
